SELECT COUNT(*) FROM project_task WHERE
status!=#{finishState} AND status !=#{approvalPassState}

    AND id IN

        #{taskId}

SELECT t.product_id AS groupFlag,COUNT(*) AS taskCount
FROM project_task t WHERE t.create_user_id=#{userId}

    AND t.status NOT IN

        #{state}


GROUP BY t.product_id

SELECT to_char(t.plan_end_time,'yyyy-MM-dd') AS groupFlag,COUNT(*) AS taskCount
FROM project_task t WHERE t.create_user_id=#{userId}
AND t.plan_end_time IS NOT NULL

    AND t.status NOT IN

        #{state}


GROUP BY t.plan_end_time

SELECT id,pid,phase_id,name,type,plan_start_time,plan_end_time,priority,status,
charge_name,quote_sys_task_id,product_id,charge_id,process_id FROM project_task
WHERE (strpos (charge_id,#{userId})>0 OR strpos (approval_user_id,#{userId})>0)

    AND product_id=#{params.groupFlag}


    AND status NOT IN

        #{state}



    AND name LIKE concat('%',#{params.searchKeyword},'%')

ORDER BY ${params.searchType} ${params.orderBy}

