SELECT id,pid,phase_id,name,type,plan_start_time,plan_end_time,priority,status,
charge_name,quote_sys_task_id,product_id,charge_id,process_id FROM project_task
WHERE   status!=#{state} AND plan_end_time < #{startTime}

select t.* from (select pi.id, pi.name as productName, pi.approval_status, pt.name as taskName, pt.plan_start_time, pt.plan_end_time, pt.reality_start_time, pt.reality_end_time, pt.status, regexp_split_to_table(pt.charge_id,',') as charge_id, regexp_split_to_table(pt.charge_name,',') as charge_name, pt.phase_name, pi2.project_status, case when pt.plan_end_time is null then 0 when pt.reality_end_time is null then 0 when to_char(pt.plan_end_time, 'YYYYMMDD') >= to_char(pt.reality_end_time, 'YYYYMMDD') then 0 when to_char(pt.reality_end_time, 'YYYYMMDD') > to_char(pt.plan_end_time, 'YYYYMMDD') then 1 else 0 end isDelay from product_info pi inner join project_task pt on pi.id = pt.product_id left join project_info pi2 on pi.id = pi2.product_id) t
and t.charge_id in
#{item}
and t.id in
#{item}
and t.status in
#{item}
and t.approval_status in
#{item}
and t.project_status in
#{item}
order by t.charge_id desc , t.id desc

